git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1508757 13f79535-47bb-0310-9956-ffa450edef68

Here is the root cause:
The performance regression in span queries was caused by the use of `ArrayUtil.timSort`, which is less efficient for small arrays compared to the newly implemented `InPlaceMergeSorter`. The previous sorting method introduced overhead that negatively impacted the performance of span queries, particularly when handling nearly sorted data.

Here is the patch:
 import org.apache.lucene.util.ArrayUtil;
 import org.apache.lucene.util.Bits;
+import org.apache.lucene.util.InPlaceMergeSorter;

 import java.io.IOException;

   private final Spans[] subSpansByDoc;
-  private final Comparator<Spans> spanDocComparator = new Comparator<Spans>() {
+  // Even though the array is probably almost sorted, InPlaceMergeSorter will likely
+  // perform better since it has a lower overhead than TimSorter for small arrays
+  private final InPlaceMergeSorter sorter = new InPlaceMergeSorter() {
     @Override
-    public int compare(Spans o1, Spans o2) {
-      return o1.doc() - o2.doc();
+    protected void swap(int i, int j) {
+      ArrayUtil.swap(subSpansByDoc, i, j);
+    }
+    @Override
+    protected int compare(int i, int j) {
+      return subSpansByDoc[i].doc() - subSpansByDoc[j].doc();
     }
   };
-  
+
   private SpanNearQuery query;
   private boolean collectPayloads = true;
   /** Advance the subSpans to the same document */
   private boolean toSameDoc() throws IOException {
-    ArrayUtil.timSort(subSpansByDoc, spanDocComparator);
+    sorter.sort(0, subSpansByDoc.length);
     int firstIndex = 0;
     int maxDoc = subSpansByDoc[subSpansByDoc.length - 1].doc();
     while (subSpansByDoc[firstIndex].doc() != maxDoc) {
       if (! subSpansByDoc[firstIndex].skipTo(maxDoc)) {
         more = false;
         inSameDoc = false;
         return false;
       }
       maxDoc = subSpansByDoc[firstIndex].doc();
       if (++firstIndex == subSpansByDoc.length) {
         firstIndex = 0;
       }
     }
     for (int i = 0; i < subSpansByDoc.length; i++) {
       assert (subSpansByDoc[i].doc() == maxDoc)
              : " NearSpansOrdered.toSameDoc() spans " + subSpansByDoc[0]
                                  + "\n at doc " + subSpansByDoc[i].doc()
                                  + ", but should be at " + maxDoc;
     }
     inSameDoc = true;
     return true;
   }



